import{_ as o,o as t,c as d,a5 as c}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"Sequence Flow — Content Writing View (FR 3.6.10)","description":"","frontmatter":{},"headers":[],"relativePath":"feature/content-task-workflow/3-6-10-content-writing-view/sequence-flow.md","filePath":"feature/content-task-workflow/3-6-10-content-writing-view/sequence-flow.md"}'),a={name:"feature/content-task-workflow/3-6-10-content-writing-view/sequence-flow.md"};function n(i,e,s,r,l,p){return t(),d("div",null,[...e[0]||(e[0]=[c('<h1 id="sequence-flow-—-content-writing-view-fr-3-6-10" tabindex="-1">Sequence Flow — Content Writing View (FR 3.6.10) <a class="header-anchor" href="#sequence-flow-—-content-writing-view-fr-3-6-10" aria-label="Permalink to &quot;Sequence Flow — Content Writing View (FR 3.6.10)&quot;">​</a></h1><p>&gt; Companion to <a href="./spec.html">spec.md</a> and <a href="./plan.html">plan.md</a> (FR 3.6.10). <strong>V6 Implemented &amp; Verified</strong> — Google Docs / Microsoft Word hybrid canvas-rendering editor + synchronized Studio editor with Yjs CRDT real-time sync &amp; peer cursor awareness over STOMP WebSocket, Document Import/Export (<code>.docx</code>, <code>.md</code>, <code>.txt</code>, <code>.html</code>, live Google Docs URL), YayText/Zantext 36-Style Unicode Font &amp; Text Effect Engine, and Dual Social Publishing Workflows (<strong>Direct API Auto-Publish</strong> to <code>Facebook</code>, <code>Instagram</code>, <code>TikTok</code>, <code>Threads</code> + <strong>Manual 1-Click Copy/Paste</strong> with Facebook Plain-Text Composer Sandbox). &gt; &gt; Updated 2026-11-09.</p><h2 id="_1-canonical-actors-components" tabindex="-1">1. Canonical Actors &amp; Components <a class="header-anchor" href="#_1-canonical-actors-components" aria-label="Permalink to &quot;1. Canonical Actors &amp; Components&quot;">​</a></h2><ul><li><strong>Actors</strong>: <code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code> (strictly following the 6 canonical BrandHub system roles).</li><li><strong>Frontend (<code>brandhub-web</code> / <code>brandhub-UI-Design</code> / <code>brandhub-mobile-app</code>)</strong>: <ul><li><code>ContentWritingPage</code> + <code>CanvasTextEditor</code> + <code>FormattingToolbar</code> + <code>ImportDocumentModal</code> + <code>SocialPreview</code> + <code>VersionHistorySidebar</code> + <code>useTaskContentSync</code>.</li><li><code>ContentCreatorStudio</code> + <code>RichTextEditor</code> + <code>StudioPreviewPanel</code>.</li><li><code>contentUtils.ts</code> — 36-Style YayText/Zantext Unicode conversion engine (<code>toPublishText</code>, <code>styleRunText</code>, <code>convertPlainTextToSocialStyle</code>, <code>stripUnicodeStyling</code>, <code>stripVietnameseAccents</code>).</li></ul></li><li><strong>Backend (<code>brandhub-business-service</code>)</strong>: <ul><li><code>TaskController</code> — <code>FR 3.6.10 — GET /api/v1/workspaces/{id}/tasks/{taskId}/content (Content Writing View)</code>, <code>@RequireRole({OWNER, MANAGER, CREATOR, CLIENT})</code>.</li><li><code>WsJwtHandshakeInterceptor</code> — validates JWT (<code>?token=</code>) on WebSocket upgrade for <code>FR 3.6.10 — WS /ws/tasks?token=&lt;JWT&gt; (Content Writing View)</code>.</li><li><code>TaskContentWebSocketController</code> — <code>@MessageMapping(&quot;/tasks/{taskId}/content&quot;)</code> and <code>@MessageMapping(&quot;/tasks/{taskId}/awareness&quot;)</code>.</li><li><code>TaskContentServiceImpl</code> — <code>getContent</code>, <code>appendOperation</code>, <code>reportSnapshot</code>, <code>listVersions</code>, <code>getVersion</code>, <code>restoreVersion</code>.</li><li><code>PostController</code> — <code>FR 3.8.5 — POST /api/v1/workspaces/{id}/posts (Preview Post)</code> and <code>FR 3.8.8 — POST /api/v1/workspaces/{id}/posts/{postId}/publish (Publish Facebook Post)</code>.</li></ul></li><li><strong>Database</strong>: PostgreSQL <code>task_content_operations</code> (append-only base64 Yjs updates) and <code>task_content_snapshots</code>.</li></ul><hr><h2 id="_2-normal-flow-—-opening-content-offline-fallback-co-backend-vs-khong-backend" tabindex="-1">2. Normal Flow — Opening Content &amp; Offline Fallback (<code>Có Backend</code> vs. <code>Không Backend</code>) <a class="header-anchor" href="#_2-normal-flow-—-opening-content-offline-fallback-co-backend-vs-khong-backend" aria-label="Permalink to &quot;2. Normal Flow — Opening Content &amp; Offline Fallback (`Có Backend` vs. `Không Backend`)&quot;">​</a></h2><ol><li><code>Creator</code> A opens <code>/workspaces/:id/content-writing?taskId=:taskId</code> (or <code>/workspaces/:id/content-writing</code>, which creates/loads a draft <code>POST</code> task).</li><li>Client A calls <code>FR 3.6.10 — GET /api/v1/workspaces/{id}/tasks/{taskId}/content (Content Writing View)</code>.</li><li><strong>Case A — Backend Reachable (<code>Có Backend</code>)</strong>: <ul><li><code>TaskContentServiceImpl</code> verifies the task belongs to the workspace and is of type <code>POST</code>, then returns <code>{ snapshot, operationsSinceSnapshot[], sequenceNumber }</code>.</li><li>Client A (<code>useTaskContentSync</code>) applies <code>snapshot</code> and replays <code>operationsSinceSnapshot</code> into its local <code>Y.Doc</code>, opens <code>FR 3.6.10 — WS /ws/tasks?token=&lt;JWT&gt; (Content Writing View)</code>, and subscribes to <code>/topic/tasks/{taskId}/content</code> and <code>/topic/tasks/{taskId}/awareness</code>.</li></ul></li><li><strong>Case B — Backend Unreachable (<code>Không Backend</code> / Offline Fallback)</strong>: <ul><li>Client A automatically switches to <code>Chế độ Ngoại tuyến</code> (<code>local-task-{workspaceId}</code>), restoring any pending updates from <code>localStorage</code> (<code>brandhub-content-pending:{taskId}</code>) so the user can continue writing, formatting, converting 36 YayText fonts, importing/exporting files, and copying to Facebook without interruption.</li></ul></li></ol><hr><h2 id="_3-normal-flow-—-real-time-collaborative-editing-sub-pixel-cursor-layout" tabindex="-1">3. Normal Flow — Real-Time Collaborative Editing &amp; Sub-Pixel Cursor Layout <a class="header-anchor" href="#_3-normal-flow-—-real-time-collaborative-editing-sub-pixel-cursor-layout" aria-label="Permalink to &quot;3. Normal Flow — Real-Time Collaborative Editing &amp; Sub-Pixel Cursor Layout&quot;">​</a></h2><ol start="5"><li><code>Creator</code> A types, pastes rich HTML, or uses Google Docs / Word shortcuts (<code>Ctrl+B/I/U</code>, <code>Ctrl+Arrow</code>, <code>Ctrl+Shift+Arrow</code>, <code>Double/Triple-click</code>).</li><li><code>CanvasTextEditor</code> applies the mutation to <code>Y.Text(&quot;content&quot;)</code> inside a <code>yDoc.transact()</code> block, measures runs via <code>measureRunSliceWidth(ctx, text, letterSpacing)</code>, and maps wrapped visual lines via <code>buildParagraphIndexMap</code> so the CSS caret and selection highlight sit at the exact sub-pixel glyph boundary.</li><li><code>useTaskContentSync</code> broadcasts <code>{ update: base64 }</code> to <code>/app/tasks/{taskId}/content</code> and <code>{ update: awarenessBase64 }</code> to <code>/app/tasks/{taskId}/awareness</code>.</li><li><code>TaskContentWebSocketController</code> persists the opaque Yjs update into <code>task_content_operations</code> with <code>sequenceNumber = count(taskId) + 1</code> and broadcasts to <code>/topic/tasks/{taskId}/content</code>.</li><li><code>Creator</code> B receives the broadcast, applies <code>Y.applyUpdate(yDoc, update, &quot;remote&quot;)</code>, and renders <code>Creator</code> A&#39;s live colored cursor flag and text update immediately.</li></ol><hr><h2 id="_4-normal-flow-—-document-import-docx-md-txt-html-google-docs-url-export" tabindex="-1">4. Normal Flow — Document Import (<code>.docx</code>, <code>.md</code>, <code>.txt</code>, <code>.html</code>, Google Docs URL) &amp; Export <a class="header-anchor" href="#_4-normal-flow-—-document-import-docx-md-txt-html-google-docs-url-export" aria-label="Permalink to &quot;4. Normal Flow — Document Import (`.docx`, `.md`, `.txt`, `.html`, Google Docs URL) &amp; Export&quot;">​</a></h2><ol start="10"><li><code>Creator</code> clicks <code>Nhập Google Docs / File</code> (<code>open-import-doc-btn</code> / <code>studio-import-doc-btn</code>).</li><li><code>ImportDocumentModal</code> either fetches the public Google Docs export stream (<code>extractGoogleDocId</code>) or parses the uploaded <code>.docx</code> (ZIP XML via <code>extractTextFromDocxBuffer</code>), <code>.md</code>, <code>.txt</code>, or <code>.html</code> into structured <code>DeltaOp[]</code> runs (preserving <code>H1</code>/<code>H2</code>/<code>H3</code>, bold, italic, underline, and bullet/numbered lists).</li><li>Depending on the selected mode (<code>Thay thế toàn bộ</code> vs. <code>Nối thêm vào cuối bài</code>), the editor applies the imported delta and updates the document title and 4-platform Live Social Preview.</li><li>From <code>Tệp</code> → <code>Tải xuống</code>, the user can export the current document losslessly to <code>.docx</code> (<code>deltaToDocxZip</code>), <code>.md</code> (<code>deltaToMarkdown</code>), or <code>.txt</code>.</li></ol><hr><h2 id="_5-normal-flow-—-yaytext-36-style-font-conversion-dual-social-publishing" tabindex="-1">5. Normal Flow — YayText 36-Style Font Conversion &amp; Dual Social Publishing <a class="header-anchor" href="#_5-normal-flow-—-yaytext-36-style-font-conversion-dual-social-publishing" aria-label="Permalink to &quot;5. Normal Flow — YayText 36-Style Font Conversion &amp; Dual Social Publishing&quot;">​</a></h2><ol start="14"><li><code>Creator</code> selects a font from the toolbar or opens <code>Font Zantext (36 Font MXH)</code> (<code>zantext-panel-trigger</code> / <code>studio-zantext-btn</code>), filters by category (<code>Tiêu đề</code>, <code>Sale &amp; Gạch giá</code>, <code>Khung Nổi bật</code>, <code>Sang trọng</code>, <code>Hiện đại</code>, <code>Độc lạ</code>, <code>⭐ Yêu thích</code>), optionally toggles <code>Lược dấu Tiếng Việt</code> or <code>Preview: iOS / Android</code>, and applies or copies any of the <strong>36 YayText / Zantext presets</strong> (e.g., <code>🅑🅤🅑🅑🅛🅔</code>, <code>🅱🅻🅰🅲🅺</code>, <code>9̸9̸0̸.̸0̸0̸0̸đ̸</code>, <code>𝐒𝐞𝐫𝐢𝐟 𝐁𝐨𝐥𝐝</code>, <code>𝓑𝓸𝓵𝓭 𝓢𝓬𝓻𝓲𝓹𝓽</code>).</li><li>On every edit, <code>toPublishText(ops)</code> converts the formatted document into a platform-safe Unicode string (<code>publishText</code>).</li><li><strong>Publishing Case 1 — Direct API Auto-Publish (<code>Đăng bài</code> / <code>Đăng ngay</code>)</strong>: <ul><li>User selects target platforms (<code>Facebook</code>, <code>Instagram</code>, <code>TikTok</code>, <code>Threads</code>) and confirms publish.</li><li>Client calls <code>FR 3.8.5 — POST /api/v1/workspaces/{id}/posts (Preview Post)</code> with <code>caption = publishText</code> and <code>FR 3.8.8 — POST /api/v1/workspaces/{id}/posts/{postId}/publish (Publish Facebook Post)</code>.</li><li>The published post banner displays the live permalink and confirms 100% of Unicode fonts, line breaks, and bullets are preserved.</li></ul></li><li><strong>Publishing Case 2 — Manual 1-Click Copy &amp; Paste (<code>Copy dán Facebook (Giữ Font)</code> / <code>Ctrl+C</code>)</strong>: <ul><li>User presses <code>Ctrl+C</code> inside the editor or clicks <code>Copy dán Facebook (Giữ Font)</code> / <code>Sao chép bản đăng</code> / row <code>Copy</code>.</li><li><code>copyTextToClipboard(convertedText)</code> writes the exact Unicode string to the system clipboard.</li><li>User can immediately paste into the built-in <strong><code>Thử dán FB</code> (Plain-Text Facebook Composer Sandbox)</strong> or directly into a normal Facebook post with 100% font retention.</li></ul></li></ol><hr><h2 id="_6-normal-flow-—-snapshots-version-history-restore" tabindex="-1">6. Normal Flow — Snapshots &amp; Version History Restore <a class="header-anchor" href="#_6-normal-flow-—-snapshots-version-history-restore" aria-label="Permalink to &quot;6. Normal Flow — Snapshots &amp; Version History Restore&quot;">​</a></h2><ol start="18"><li>After 200 operations or 20 seconds of idle time after an edit, the client calls <code>FR 3.6.10 — POST /api/v1/workspaces/{id}/tasks/{taskId}/content/snapshot (Content Writing View)</code>.</li><li><code>VersionHistorySidebar</code> loads <code>FR 3.6.34 — GET /api/v1/workspaces/{id}/tasks/{taskId}/content/versions (View Content History)</code> and <code>FR 3.6.34 — GET /api/v1/workspaces/{id}/tasks/{taskId}/content/versions/{snapshotId} (View Content History)</code> to display word-level diffs (<code>diffText</code>).</li><li>Clicking <code>Restore</code> calls <code>FR 3.6.10 — POST /api/v1/workspaces/{id}/tasks/{taskId}/content/versions/{snapshotId}/restore (Content Writing View)</code>, which appends a new forward snapshot and broadcasts the restored state via Yjs without erasing prior history.</li></ol><hr><h2 id="_7-error-paths" tabindex="-1">7. Error Paths <a class="header-anchor" href="#_7-error-paths" aria-label="Permalink to &quot;7. Error Paths&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Step</th><th>Failure Condition</th><th>HTTP / WS</th><th>Error Code / Fallback</th></tr></thead><tbody><tr><td>Open content</td><td>Task does not exist or belongs to a different Workspace</td><td>404</td><td><code>TASK_NOT_FOUND</code> (<code>MSG04</code>)</td></tr><tr><td>Open content</td><td>Task is not of type <code>POST</code></td><td>400</td><td><code>INVALID_TASK_TYPE_FOR_CONTENT_WRITING</code> (<code>MSG12</code>)</td></tr><tr><td>Open content</td><td>Backend unreachable (<code>503</code> / network error)</td><td>Fallback</td><td>Switches to <code>Chế độ Ngoại tuyến</code> (<code>continue-offline-btn</code>)</td></tr><tr><td>Open content</td><td>Caller is not an authorized workspace member</td><td>403</td><td><code>FORBIDDEN</code> (<code>@RequireRole</code>)</td></tr><tr><td>WS handshake</td><td>JWT missing or invalid</td><td>Handshake rejected</td><td>401 (<code>WsJwtHandshakeInterceptor</code>)</td></tr><tr><td>Import Google Doc</td><td>Google Docs link is private or malformed</td><td>Client / 400</td><td>Displays Vietnamese sharing guide + <code>.docx</code> upload fallback</td></tr><tr><td>Restore</td><td><code>snapshotId</code> not found or belongs to a different Task</td><td>404</td><td><code>TASK_NOT_FOUND</code></td></tr></tbody></table>',22)])])}const m=o(a,[["render",n]]);export{u as __pageData,m as default};
